export function languageFromUrl(url){return new URL(url).searchParams.get('lang')==='ru'?'ru':'en';}
export function languageUrl(url,language){const u=new URL(url);if(language==='ru')u.searchParams.set('lang','ru');else u.searchParams.delete('lang');return u.pathname+u.search+u.hash;}
export const staticEnglish=text=>copy[text]??text;
export function translate(text,language){return language==='ru'?text:staticEnglish(text);}
const fragments=Object.keys(copy).sort((a,b)=>b.length-a.length);
export function localizeMessage(message,language){if(language==='ru'||!message)return message;let result=String(message);for(const source of fragments)result=result.split(source).join(copy[source]);return result;}
export function localizeDocument(doc,language){doc.documentElement.lang=language;const walker=doc.createTreeWalker(doc.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){const raw=node.nodeValue,trimmed=raw.trim();if(copy[trimmed]&&language==='en')node.nodeValue=raw.replace(trimmed,copy[trimmed]);}for(const el of doc.querySelectorAll('[title],[aria-label],meta[name="description"]'))for(const attr of ['title','aria-label','content']){const value=el.getAttribute(attr);if(value&&copy[value]&&language==='en')el.setAttribute(attr,copy[value]);}}
